// Fixture batch 132: conic, curvature and uneven fillets of curved edges. Generated by tools/fixtures/gen-batch-132.mjs; do not edit.
// Each case builds its geometry at the origin and may return a map of values to check.

function round6(v) returns array
{
    return [roundToPrecision(v[0] / millimeter, 6), roundToPrecision(v[1] / millimeter, 6), roundToPrecision(v[2] / millimeter, 6)];
}

// The blend's faces: each one's area, and each of its edges' points at eight places round.
function blendProbe(context is Context, faces is Query) returns array
{
    var out = [];
    for (var face in evaluateQuery(context, faces))
    {
        var edges = [];
        for (var edge in evaluateQuery(context, qAdjacent(face, AdjacencyType.EDGE, EntityType.EDGE)))
        {
            const lines = evEdgeTangentLines(context, { "edge" : edge, "parameters" : [0, 0.125, 0.25, 0.375, 0.5, 0.625, 0.75, 0.875], "arcLengthParameterization" : false });
            var points = [];
            for (var l in lines)
                points = append(points, round6(l.origin));
            edges = append(edges, points);
        }
        out = append(out, { "area" : roundToPrecision(evArea(context, { "entities" : face }) / millimeter ^ 2, 6), "edges" : edges });
    }
    return out;
}

// fillet: a tee of a pipe of radius 10 and a branch of radius 3: the joint filleted 1 mm with a conic section, rho 0.5
export function c001(context is Context, id is Id)
{
    const baseSketch = newSketchOnPlane(context, id + "baseSketch", { "sketchPlane" : plane(vector(-25, 0, 0) * millimeter, vector(1, 0, 0), vector(0, 1, 0)) });
    skCircle(baseSketch, "circle1", { "center" : vector(0, 0) * millimeter, "radius" : 10 * millimeter });
    skSolve(baseSketch);
    extrude(context, id + "base", { "entities" : qSketchRegion(id + "baseSketch"), "endBound" : BoundingType.BLIND, "depth" : 50 * millimeter });
    const branchSketch = newSketchOnPlane(context, id + "branchSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skCircle(branchSketch, "circle1", { "center" : vector(0, 0) * millimeter, "radius" : 3 * millimeter });
    skSolve(branchSketch);
    extrude(context, id + "branch", { "entities" : qSketchRegion(id + "branchSketch"), "endBound" : BoundingType.BLIND, "depth" : 20 * millimeter, "operationType" : NewBodyOperationType.ADD, "defaultScope" : false, "booleanScope" : qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID) });
    fillet(context, id + "fillet1", { "entities" : qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.EDGE), vector(3, 0, 10) * millimeter), "radius" : 1 * millimeter, "crossSection" : FilletCrossSection.CONIC, "nonCircularRadius" : 1 * millimeter, "rho" : 0.5 });
    return { "fillet" : blendProbe(context, qCreatedBy(id + "fillet1", EntityType.FACE)) };
}

